83	COMMENT ON COLUMN unblind_request.experiment_id IS '所属实验编号';
84	COMMENT ON COLUMN unblind_request.participant_id IS '被申请揭盲的合成参与者编号';
85	COMMENT ON COLUMN unblind_request.allocation_id IS '对应分配主键';
86	COMMENT ON COLUMN unblind_request.reason IS '揭盲原因，必填，非空';
87	COMMENT ON COLUMN unblind_request.applicant_actor IS '申请人操作者编号，须为 COORDINATOR，且只有其本人能查询揭盲结果';
