95	CREATE TABLE IF NOT EXISTS idempotent_request (
96	    request_id      VARCHAR(64)  NOT NULL,
97	    actor_id        VARCHAR(64)  NOT NULL,
98	    role            VARCHAR(16)  NOT NULL,
99	    operation       VARCHAR(64)  NOT NULL,
100	    fingerprint     VARCHAR(128) NOT NULL,
101	    response_status INT          NOT NULL,
102	    response_body   CLOB,
103	    created_at      BIGINT       NOT NULL,
104	    CONSTRAINT pk_idempotent_request PRIMARY KEY (request_id)
105	);
