        SiteActivationRow latest = siteActivationRepository.findLatest(experimentId, siteCode);
        if (latest != null && latest.activationKey().equals(activationKey)
                && (latest.firstActor().equals(actorId) || latest.secondActor().equals(actorId))) {
            return new ActivationConfirmView(..., true);
        }
        throw conflict("中心已激活，重复确认被拒绝");
    }
    long now = clock.nowMillis();
    if (site.pendingActor() == null) {
        siteRepository.recordFirstConfirmation(...);
        return new ActivationConfirmView(expId, siteCode, site.status(), site.generation(), key, actorId, now, null, null, false);
